/**
 * Licensed stock media (Wikimedia Commons / Pexels / Pixabay), motion-graphics
 * compositing and in-video check questions.
 *
 * No network: provider searches and downloads are stubbed with local fixture
 * files generated by FFmpeg. Everything else (ranking, licence filtering,
 * normalisation, storage cache, rendering, FFmpeg compositing, the worker
 * pipeline) is the production code path.
 */
const { startDb, stopDb, oid, silenceLogs, TMP } = require('./helpers/setup');
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const Course = require('../src/models/Course');
const CourseBuildJob = require('../src/models/CourseBuildJob');
const CourseBuildItem = require('../src/models/CourseBuildItem');
const GenerationJob = require('../src/models/GenerationJob');
const storage = require('../src/services/video/storage.service');
const ai = require('../src/services/course-builder/ai.service');
const providers = require('../src/services/video/media/providers');
const stock = require('../src/services/video/media/stock-media.service');
const { validateStoryboard } = require('../src/services/video/storyboard.service');
const { subjectByKey } = require('../src/services/video/subjects');
const { framesFor, renderFrame, layoutOf } = require('../src/services/video/render/scene-html');
const assembler = require('../src/services/video/render/assembler');
const pipeline = require('../src/services/video/pipeline.service');
const videoJobs = require('../src/services/video/video-jobs.service');
const { JobWorker } = require('../src/services/jobs/worker.service');

const FFMPEG = process.env.FFMPEG_BIN || 'ffmpeg';
const FIX = path.join(TMP, 'stock-fixtures');
const PHOTO = path.join(FIX, 'photo.jpg');
const CLIP = path.join(FIX, 'clip.mp4');
const realFetch = global.fetch;
const realSearch = providers.PROVIDERS.wikimedia.search;
const original = { completeJson: ai.completeJson };
let restoreLogs;
let downloads = 0;

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

/** A Commons-style candidate pointing at a local fixture. */
function cand(id, kind, title, extra = {}) {
  return {
    provider: 'wikimedia', id: String(id), kind, downloadUrl: `https://fixtures.test/${kind === 'video' ? 'clip.mp4' : 'photo.jpg'}`,
    width: kind === 'video' ? 1280 : 1600, height: kind === 'video' ? 720 : 1000, durationSec: kind === 'video' ? 4 : null, bytes: 1000,
    title, text: title, author: 'Test Author', authorUrl: null, sourceUrl: `https://commons.wikimedia.org/wiki/File:${id}.jpg`,
    license: 'CC BY 4.0', licenseUrl: 'https://creativecommons.org/licenses/by/4.0', attributionRequired: true, providerLabel: 'Wikimedia Commons',
    ...extra,
  };
}

/** Stubbed search index: query words → candidates. */
function stubSearch(query, { kind }) {
  const q = query.toLowerCase();
  const all = [
    cand(101, 'image', 'Quadrat frame on grass during ecology fieldwork'),
    cand(102, 'image', 'Students measuring a line transect across a meadow'),
    cand(103, 'video', 'Wetland lake shore with reeds in the wind'),
    cand(104, 'image', 'Lake shore wetland reeds'),
    cand(105, 'image', 'Car engine repair'), // irrelevant, must never be picked
  ];
  return Promise.resolve(all.filter(c => c.kind === kind && q.split(/\s+/).some(w => w.length > 3 && c.text.toLowerCase().includes(w))));
}

test.before(async () => {
  restoreLogs = silenceLogs();
  fs.mkdirSync(FIX, { recursive: true });
  execFileSync(FFMPEG, ['-y', '-v', 'error', '-f', 'lavfi', '-i', 'testsrc=size=1600x1000:rate=1', '-frames:v', '1', PHOTO]);
  execFileSync(FFMPEG, ['-y', '-v', 'error', '-f', 'lavfi', '-i', 'testsrc2=size=1280x720:rate=25', '-t', '4', '-pix_fmt', 'yuv420p', CLIP]);
  global.fetch = async (url, opts) => {
    const u = String(url);
    if (!u.startsWith('https://fixtures.test/')) return realFetch(url, opts);
    downloads++;
    const file = u.endsWith('.mp4') ? CLIP : PHOTO;
    const buf = fs.readFileSync(file);
    return new Response(buf, { status: 200, headers: { 'content-type': u.endsWith('.mp4') ? 'video/mp4' : 'image/jpeg', 'content-length': String(buf.length) } });
  };
  providers.PROVIDERS.wikimedia.search = stubSearch;
  await startDb();
});

test.after(async () => {
  global.fetch = realFetch;
  providers.PROVIDERS.wikimedia.search = realSearch;
  Object.assign(ai, original);
  await stopDb();
  restoreLogs();
});

// ─── providers: licences and normalisation ───────────────────────────────────

test('commons licences: CC BY / CC0 / public domain allowed, NC / ND / unknown rejected, BY-SA opt-in', () => {
  assert.deepEqual(providers.commonsLicense('CC BY 4.0', false), { license: 'CC BY 4.0', attributionRequired: true });
  assert.equal(providers.commonsLicense('CC0', false).attributionRequired, false);
  assert.equal(providers.commonsLicense('Public domain', false).attributionRequired, false);
  assert.equal(providers.commonsLicense('CC BY-NC 4.0', true), null);
  assert.equal(providers.commonsLicense('CC BY-NC-SA 3.0', true), null);
  assert.equal(providers.commonsLicense('CC BY-ND 2.0', true), null);
  assert.equal(providers.commonsLicense('Fair use', true), null);
  assert.equal(providers.commonsLicense('CC BY-SA 4.0', false), null);
  assert.equal(providers.commonsLicense('CC BY-SA 4.0', true).shareAlike, true);
});

test('commons page (real API shape) is normalised with credit, thumbnail and searchable text', () => {
  const page = {
    pageid: 156016044, title: 'File:Quadrat sur le site du Vivier Basque (Ifremer 00561-67277).jpg', index: 1,
    imageinfo: [{
      size: 3281213, width: 3072, height: 2304, thumburl: 'https://upload.wikimedia.org/thumb/1280px-q.jpg', thumbwidth: 1280, thumbheight: 960,
      url: 'https://upload.wikimedia.org/q.jpg', descriptionurl: 'https://commons.wikimedia.org/wiki/File:Quadrat.jpg', mime: 'image/jpeg',
      extmetadata: {
        ImageDescription: { value: 'The quadrat photographed here makes it possible to isolate a sample <sup>m2</sup>' },
        Artist: { value: '<a href="x">Marie-Noelle de Casamajor</a>' },
        LicenseShortName: { value: 'CC BY 4.0' }, LicenseUrl: { value: 'https://creativecommons.org/licenses/by/4.0' },
        Categories: { value: 'Quadrats|Ecology fieldwork' },
      },
    }],
  };
  const c = providers.normalizeCommonsPage(page, 'image');
  assert.equal(c.downloadUrl, 'https://upload.wikimedia.org/thumb/1280px-q.jpg');
  assert.equal(c.width, 1280);
  assert.equal(c.author, 'Marie-Noelle de Casamajor');
  assert.equal(c.attributionRequired, true);
  assert.match(c.text, /Ecology fieldwork/);
  assert.equal(providers.normalizeCommonsPage(page, 'video'), null, 'kind mismatch rejected');
  const nc = JSON.parse(JSON.stringify(page));
  nc.imageinfo[0].extmetadata.LicenseShortName.value = 'CC BY-NC 4.0';
  assert.equal(providers.normalizeCommonsPage(nc, 'image'), null, 'non-commercial licence rejected');
});

