test('storyboard: media scenes, media on slides, checks expand into question + answer', () => {
  const lessonText = 'Five quadrats of 1 m2 contain 25 plants, so the density is 5 plants per m2.';
  const { storyboard, warnings } = validateStoryboard({
    scenes: [
      { type: 'title', heading: 'Sampling', narration: 'Hello.', media: { query: 'quadrat frame grass', kind: 'video', alternatives: ['quadrat', 'quadrat frame grass'] } },
      { type: 'media', heading: 'In the field', points: ['Random placement'], media: { query: 'quadrat frame grass' }, narration: 'Look at the field.' },
      { type: 'media', heading: 'No media', points: ['A point'], narration: 'No query given.' },
      { type: 'bullets', heading: 'Steps', bullets: ['Place', 'Count'], media: { query: 'students counting plants', kind: 'image' }, narration: 'Place and count.' },
      { type: 'check', question: 'What is the density?', choices: ['5 per m2', '25 per m2', '5 per m2'], answerIndex: 0, explanation: '25 ÷ 5 = 5', narration: 'Pause and think.', answerNarration: 'It is 5 per square metre.' },
      { type: 'check', question: 'Broken', choices: ['only one'], answerIndex: 0, narration: 'x' },
      { type: 'check', question: 'Invented?', choices: ['7 per m2', '9 per m2'], answerIndex: 1, explanation: '', narration: 'Think.' },
      { type: 'summary', heading: 'Done', bullets: ['Sample'], narration: 'Bye.' },
    ],
  }, { allowedTypes: subjectByKey('biology').scenes, lessonText, lessonTitle: 'Sampling' });

  const types = storyboard.scenes.map(s => s.type);
  assert.deepEqual(types, ['title', 'media', 'bullets', 'bullets', 'check', 'check_answer', 'check', 'check_answer', 'summary']);
  assert.deepEqual(storyboard.scenes[0].media, { query: 'quadrat frame grass', kind: 'video', alternatives: ['quadrat'] });
  assert.equal(storyboard.scenes[2].type, 'bullets', 'media scene without a query becomes points');
  assert.equal(storyboard.scenes[3].media.kind, 'image');
  const q = storyboard.scenes[4];
  assert.deepEqual(q.choices, ['5 per m2', '25 per m2'], 'duplicate choices removed');
  assert.equal(q.answerNarration, undefined, 'answer narration moved to the reveal scene');
  assert.equal(storyboard.scenes[5].narration, 'It is 5 per square metre.');
  assert.equal(storyboard.scenes[5].answerIndex, 0);
  assert.ok(warnings.some(w => /invalid check/.test(w)));
  assert.ok(warnings.some(w => /numbers not in the lesson \(9\)/.test(w)), 'unverifiable answer key flagged for review');
  assert.deepEqual(storyboard.scenes.map(s => s.n), [1, 2, 3, 4, 5, 6, 7, 8, 9]);
});

