test('layouts, frame states and transparent overlays', () => {
  const asset = { credit: 'Photo: A / Wikimedia Commons · CC BY 4.0' };
  assert.equal(layoutOf({ type: 'media' }, asset), 'full');
  assert.equal(layoutOf({ type: 'bullets' }, asset), 'split');
  assert.equal(layoutOf({ type: 'formula' }, asset), 'none', 'exact content never sits on stock media');
  assert.equal(layoutOf({ type: 'media' }, null), 'none');
  const check = { type: 'check', n: 2, question: 'Q?', choices: ['a', 'b', 'c'], answerIndex: 1 };
  const states = framesFor(check);
  assert.equal(states.length, 4);
  assert.ok(states[0].first && states[3].think);
  const ctx = { lessonTitle: 'L', subjectLabel: 'biology', totalScenes: 3, figures: new Map(), media: new Map([[1, asset]]) };
  const split = renderFrame({ type: 'bullets', n: 1, heading: 'H', bullets: ['x'] }, { reveal: 1, first: true }, ctx);
  assert.match(split, /background:transparent/);
  assert.match(split, /class="bgmask"/);
  assert.match(split, /CC BY 4\.0/, 'credit shown on screen');
  const answer = renderFrame({ ...check, type: 'check_answer', explanation: 'because' }, { answer: true }, ctx);
  assert.match(answer, /choice on correct"><span class="letter">✓/);
});

test('frame list timing: animation frames + hold add up to the scene length', () => {
  const list = assembler.frameList([{ anim: ['a1', 'a2', 'a3'], hold: 'h1' }, { anim: [], hold: 'h2' }], 6, 15);
  const total = [...list.matchAll(/duration ([\d.]+)/g)].reduce((a, m) => a + parseFloat(m[1]), 0);
  assert.ok(Math.abs(total - 6) < 0.01, `total ${total}`);
  assert.match(list, /file 'h2'\n?$/);
});

test('step-by-step narration: each step stays on screen while its own part is spoken', async () => {
  // Uneven explanations: the first line is held 5 s, the second 1 s, the last gets the rest.
  const list = assembler.frameList([{ anim: [], hold: 's1' }, { anim: [], hold: 's2' }, { anim: [], hold: 's3' }], 10, 15, { durations: [5, 1, 4] });
  assert.deepEqual([...list.matchAll(/duration ([\d.]+)/g)].map(m => parseFloat(m[1])), [5, 1, 4]);

  // Parts are joined with a pause after every part except the last.
  const work = fs.mkdtempSync(path.join(TMP, 'parts-'));
  const tone = (name, sec) => {
    const f = path.join(work, name);
    execFileSync(FFMPEG, ['-y', '-v', 'error', '-f', 'lavfi', '-i', `sine=frequency=440:duration=${sec}`, f]);
    return f;
  };
  const joined = await assembler.joinAudio([tone('a.wav', 1), tone('b.wav', 2), tone('c.wav', 1)], 0.8, path.join(work, 'joined.wav'));
  const seconds = await assembler.mediaDuration(joined);
  assert.ok(Math.abs(seconds - (1 + 2 + 1 + 2 * 0.8)) < 0.1, `joined ${seconds}`);
});

test('buildSegment composites a Ken Burns photo (split) and a clip (full) under transparent overlays', async () => {
  const work = fs.mkdtempSync(path.join(TMP, 'seg-'));
  const overlay = path.join(work, 'ov.png');
  // transparent overlay with an opaque bar at the top
  execFileSync(FFMPEG, ['-y', '-v', 'error', '-f', 'lavfi', '-i', 'color=c=white:s=1280x100,format=rgba,pad=1280:720:0:0:color=black@0', '-frames:v', '1', overlay]);
  const cases = [
    { name: 'photo-split', background: { kind: 'image', file: PHOTO, rect: { x: 712, y: 156, w: 508, h: 400 }, motion: 2 } },
    { name: 'clip-full', background: { kind: 'video', file: CLIP, durationSec: 4, motion: 1 } },
  ];
  for (const c of cases) {
    const out = path.join(work, `${c.name}.mp4`);
    const seg = await assembler.buildSegment({ states: [{ anim: [], hold: overlay }], audioFile: null, audioSeconds: 5, outFile: out, background: c.background });
    const info = await assembler.probe(out);
    assert.ok(Math.abs(parseFloat(info.format.duration) - seg.seconds) < 0.2, `${c.name} duration`);
    // Pixel check: the top bar is the overlay (white); the middle shows the media (not white).
    const px = (y) => execFileSync(FFMPEG, ['-v', 'error', '-ss', '2', '-i', out, '-frames:v', '1', '-vf', `crop=40:40:${c.name === 'photo-split' ? 940 : 620}:${y},scale=1:1`, '-f', 'rawvideo', '-pix_fmt', 'gray', '-']);
    assert.ok(px(30)[0] > 235, `${c.name}: overlay on top`);
    assert.ok(px(330)[0] < 235, `${c.name}: media visible underneath (${px(330)[0]})`);
  }
});

