test('worker renders a lesson with real-world media, a check question and credits', async () => {
  process.env.VIDEO_STOCK_MEDIA = 'true';
  process.env.VIDEO_STOCK_PROVIDERS = 'wikimedia';
  ai.completeJson = async () => ({
    title: 'Sampling',
    scenes: [
      { type: 'title', heading: 'Sampling populations', subtitle: 'Quadrats and transects', narration: 'Ecologists estimate populations by sampling.', media: { query: 'wetland lake shore', kind: 'video' } },
      { type: 'media', heading: 'Quadrats in the field', points: ['Square frame', 'Random spots'], narration: 'A quadrat is a square frame placed at random spots.', media: { query: 'quadrat frame grass', kind: 'image' } },
      { type: 'bullets', heading: 'Line transects', bullets: ['Tape across a habitat', 'Record at intervals'], narration: 'A line transect records changes across a habitat.', media: { query: 'line transect meadow', kind: 'image' } },
      { type: 'check', question: 'Five 1 m2 quadrats hold 25 plants. Density?', choices: ['5 plants per m2', '25 plants per m2', '125 plants per m2'], answerIndex: 0, explanation: '25 ÷ 5 m2 = 5 per m2', narration: 'Five quadrats hold twenty five plants. What is the density? Pause and choose.', answerNarration: 'The density is five plants per square metre.' },
      { type: 'table', heading: 'Counts', columns: ['Quadrat', 'Plants'], rows: [['1', '4'], ['2', '6']], narration: 'Here are the counts per quadrat.', media: { query: 'quadrat frame grass' } },
      { type: 'summary', heading: 'Key takeaways', bullets: ['Sample, then scale up'], narration: 'Sample a small area, then scale up.' },
    ],
  });
  const userId = oid();
  const course = await Course.create({ title: 'Biology S6', description: 'Biology', createdBy: userId, price: 0, duration: 10, level: 'advanced' });
  const job = await CourseBuildJob.create({ courseId: course._id, createdBy: userId, status: 'generating', outline: { subject: 'Biology', bookTitle: 'Biology', level: 'S6' } });
  const item = await CourseBuildItem.create({
    jobId: job._id, courseId: course._id, kind: 'lesson', chapterIndex: 0, title: 'Sampling', status: 'draft', contentVersion: 1,
    content: { summary: 'Sampling estimates populations.', notes: 'Five quadrats of 1 m2 contain 25 plants, so the density is 5 plants per m2.' },
  });
  const worker = new JobWorker({ pollMs: 100, concurrency: 1, log: { info: () => {}, error: () => {} } });
  worker.register('lesson_video', pipeline.runLessonVideo, { timeoutMs: 240000 });
  await worker.start();
  try {
    const { job: gj } = await videoJobs.enqueueVideo({ buildJob: job, item, variant: 'explainer' });
    let done;
    for (let i = 0; i < 1200 && !done; i++) {
      const j = await GenerationJob.findById(gj._id).lean();
      if (j.state === 'failed') throw new Error(`video failed: ${j.error?.message}`);
      if (j.state === 'completed') done = j;
      else await sleep(200);
    }
    assert.ok(done, 'video completed');
    const o = done.output;
    assert.deepEqual(done.artifacts.storyboard.scenes.map(s => s.type), ['title', 'media', 'bullets', 'check', 'check_answer', 'table', 'summary']);
    const media = done.artifacts.media;
    assert.deepEqual(media.map(m => [m.scene, m.kind]), [[1, 'video'], [2, 'image'], [3, 'image']], 'tables (exact content) never get stock media');
    assert.equal(o.credits.length, 3);
    assert.ok(o.credits.every(c => c.license === 'CC BY 4.0' && c.attributionRequired));

    // The app pauses after the question narration, before the answer reveal.
    assert.equal(o.interactions.length, 1);
    const it = o.interactions[0];
    assert.equal(it.answerIndex, 0);
    assert.ok(it.at > 0 && it.at < it.resumeAt && it.resumeAt < o.durationSeconds);
    assert.ok(it.resumeAt - it.at >= pipeline.THINK_SECONDS - 0.5, 'thinking pause kept in the video');

    // Video = scenes + 4 s credits; every quality check passes except silent narration (test TTS).
    assert.ok(done.checks.filter(c => c.name !== 'narration').every(c => c.passed), JSON.stringify(done.checks));
    const file = path.join(process.env.MEDIA_LOCAL_DIR, o.s3Key);
    const lum = (t) => execFileSync(FFMPEG, ['-v', 'error', '-ss', String(t), '-i', file, '-frames:v', '1', '-vf', 'scale=1:1', '-f', 'rawvideo', '-pix_fmt', 'gray', '-'])[0];
    assert.ok(lum(1.5) < 200, 'title scene shows the clip under a dark scrim');
    assert.ok(lum(o.durationSeconds - 1.5) > 200, 'credits slide at the end');

    // Saved on the draft for the app.
    const saved = await CourseBuildItem.findById(item._id).lean();
    assert.equal(saved.video.interactions.length, 1);
    assert.equal(saved.video.credits.length, 3);
  } finally {
    await worker.stop(1000);
    process.env.VIDEO_STOCK_MEDIA = 'false';
  }
});

test('ElevenLabs narration: teacher settings, request stitching, default voice/model', () => {
  const tts = require('../src/services/video/providers/tts');
  const saved = { ...process.env };
  try {
    delete process.env.ELEVENLABS_MODEL_ID;
    delete process.env.ELEVENLABS_VOICE_ID;
    const first = tts.elevenRequest('Hello class.', { nextText: 'Next scene.' });
    assert.equal(first.model_id, 'eleven_multilingual_v2');
    assert.deepEqual(first.voice_settings, { stability: 0.5, similarity_boost: 0.75, style: 0.15, use_speaker_boost: true, speed: 0.85 });
    assert.equal(first.next_text, 'Next scene.');
    assert.equal(first.previous_request_ids, undefined);
    const later = tts.elevenRequest('Now notice…', { previousText: 'ignored when ids exist', previousRequestIds: ['a', 'b', 'c', 'd'] });
    assert.deepEqual(later.previous_request_ids, ['b', 'c', 'd'], 'at most 3, most recent');
    assert.equal(later.previous_text, undefined);
    assert.equal(tts.elevenRequest('x', { previousText: 'prev' }).previous_text, 'prev');
    process.env.ELEVENLABS_MODEL_ID = 'eleven_v3';
    const v3 = tts.elevenRequest('x', { previousRequestIds: ['a'], nextText: 'n' });
    assert.equal(v3.previous_request_ids, undefined, 'eleven_v3 does not support stitching');
    assert.equal(v3.next_text, undefined);
    process.env.ELEVENLABS_MODEL_ID = 'eleven_multilingual_v2';
    process.env.ELEVENLABS_SPEED = '3';
    assert.equal(tts.elevenRequest('x').voice_settings.speed, 1.2, 'speed clamped');
    const a = tts.PROVIDERS.elevenlabs.signature();
    process.env.ELEVENLABS_VOICE_ID = 'otherVoice';
    assert.notEqual(tts.PROVIDERS.elevenlabs.signature(), a, 'changing the voice re-records narration');
  } finally {
    for (const k of Object.keys(process.env)) if (!(k in saved)) delete process.env[k];
    Object.assign(process.env, saved);
  }
});

test('retries reuse the media already chosen (no new searches)', async () => {
  const work = fs.mkdtempSync(path.join(TMP, 'reuse-'));
  await storage.put('stock-media/wikimedia/301.jpg', PHOTO, 'image/jpeg');
  providers.PROVIDERS.wikimedia.search = async () => { throw new Error('must not search'); };
  try {
    const job = { artifacts: { media: [{ scene: 1, key: 'stock-media/wikimedia/301.jpg', kind: 'image', provider: 'wikimedia', id: '301' }], mediaWarnings: ['w'] } };
    const { media, warnings } = await pipeline.loadOrFindMedia(job, { scenes: [{ n: 1, media: { query: 'x' } }] }, work, { saveArtifacts: async () => { throw new Error('must not save'); } });
    assert.ok(fs.existsSync(media.get(1).file));
    assert.deepEqual(warnings, ['w']);
  } finally {
    providers.PROVIDERS.wikimedia.search = stubSearch;
  }
});
